    // Buffers carries the buffers' Span views. An extension on `ref this` is how
    // C# 9 returns a view into a struct's own storage.
    public static class Buffers
    {
        public static Span<T> AsSpan<T>(ref this Buffer1<T> buffer) where T : unmanaged
        {
            return MemoryMarshal.CreateSpan(ref buffer.E0, Buffer1<T>.Capacity);
        }

