    // Schema carries the unit's generated functions and constants — C# has no
    // namespace-level members (SPEC §6.1 naming); partial, one slice per file.
    public static partial class Schema
    {
        // The unit's protocol id — the hash of its wire shape (SPEC §3.1). Two
        // sides at the same id speak identical bits; there is no other versioning.
        public const ulong ProtocolId = 0xeb26c970fde3fd71;

        public const long PositionUnits = 1024;

        public const long VelocityUnits = 1024;

        public const long RotationUnits = 1024;

        public const long MaxWorldMeters = 8192;

        public const long MaxPositionUnits = 8388608; // = MaxWorldMeters * PositionUnits

        public const long MaxSpeedMeters = 2048;

        public const long MaxVelocityUnits = 2097152; // = MaxSpeedMeters * VelocityUnits

        public const long MaxHealth = 1000;

        public const long MaxObjects = 10000;

        public const long ShipMaxLasers = 16;

        public const long ShipMaxMissiles = 16;

        public const long NumTeams = 2; // = Team.Max

        public const long MaxInputsPerPacket = 16;

        public const long MaxBlockSize = 2000;

        public const long MaxChatLength = 256;

        // ValidUtf8Text: well-formed UTF-8 (Unicode Table 3-7) with no zero byte —
        // the content a string(N) read accepts (SPEC §4.7).
        internal static bool ValidUtf8Text(ReadOnlySpan<byte> text)
        {
            for (int i = 0; i < text.Length;)
            {
                int lead = text[i++];
                if (lead < 0x80)
                {
                    if (lead == 0)
                    {
                        return false;
                    }
                    continue;
                }
                int remaining, point;
                if ((lead & 0xE0) == 0xC0)
                {
                    remaining = 1;
                    point = lead & 0x1F;
                }
                else if ((lead & 0xF0) == 0xE0)
                {
                    remaining = 2;
                    point = lead & 0x0F;
                }
                else if ((lead & 0xF8) == 0xF0)
                {
                    remaining = 3;
                    point = lead & 0x07;
                }
                else
                {
                    return false;
                }
                if (remaining > text.Length - i)
                {
                    return false;
                }
                for (int part = 0; part < remaining; part++)
                {
                    int next = text[i++];
                    if ((next & 0xC0) != 0x80)
                    {
                        return false;
                    }
                    point = (point << 6) | (next & 0x3F);
                }
                if ((remaining == 1 && point < 0x80)
                    || (remaining == 2 && (point < 0x800 || (point >= 0xD800 && point <= 0xDFFF)))
                    || (remaining == 3 && (point < 0x10000 || point > 0x10FFFF)))
                {
                    return false;
                }
            }
            return true;
        }
    }
